extensibilityCode.react:
// Toggle de formatação com tracking
const [isBold, setIsBold] = useState(false);

<Toggle
  pressed={isBold}
  onPressedChange={(next) => {
    track('field_change', {
      component: 'toggle',
      field_name: 'bold',
      value: String(next),
    });
    setIsBold(next);
  }}
  aria-label="Negrito"
>
  <Bold aria-hidden="true" />
</Toggle>

