customizationCode.web:
/* Cor do estado ativo numa instância só: sobrescreva os tokens que a
   folha do componente já lê. */
.toggle-brand {
  --accent: 217 91% 60%;
  --accent-foreground: 0 0% 100%;
}

/* Recuo próprio num degrau de tamanho. A altura NÃO se crava: ela nasce do
   recuo vertical mais a tipografia, para o controle crescer junto quando a
   pessoa aumenta a fonte do navegador. */
.nds-toggle[data-size="lg"] {
  padding-inline: var(--spacing-4);
}

